class Solution {
    public int islandPerimeter(int[][] grid) {
        int rows = grid.length, cols = grid[0].length;
        int perimeter = 0;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == 1) {
                    perimeter += 4;
                    if (i > 0 && grid[i - 1][j] == 1) perimeter -= 2;
                    if (j > 0 && grid[i][j - 1] == 1) perimeter -= 2;
                }
            }
        }
        return perimeter;
    }
}

class Solution {
    public int islandPerimeter(int[][] grid) {
        int rows = grid.length, cols = grid[0].length;
        boolean[][] visited = new boolean[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == 1) {
                    return dfs(grid, visited, i, j, rows, cols);
                }
            }
        }
        return 0;
    }

    private int dfs(int[][] grid, boolean[][] visited, int i, int j, int rows, int cols) {
        if (i < 0 || i >= rows || j < 0 || j >= cols || grid[i][j] == 0) return 1;
        if (visited[i][j]) return 0;
        visited[i][j] = true;
        int perim = 0;
        perim += dfs(grid, visited, i - 1, j, rows, cols);
        perim += dfs(grid, visited, i + 1, j, rows, cols);
        perim += dfs(grid, visited, i, j - 1, rows, cols);
        perim += dfs(grid, visited, i, j + 1, rows, cols);
        return perim;
    }
}
